 private String js(String code)throws Exception{CountDownLatch done=new CountDownLatch(1);AtomicReference<String> value=new AtomicReference<>();runOnMainSync(()->web.evaluateJavascript(code,v->{value.set(v);done.countDown();}));if(!done.await(15,TimeUnit.SECONDS))throw new Exception("JS timeout");return value.get();}
 private void waitJS(String code)throws Exception{for(int i=0;i<100;i++){if("true".equals(js(code)))return;Thread.sleep(100);}throw new Exception("UI check failed: "+code);}
 private JSONObject status()throws Exception{return new JSONObject(PlaybackService.status());}
 private JSONObject await(String field,String value)throws Exception{for(int i=0;i<100;i++){JSONObject s=status();if(s.optJSONObject("item")!=null&&value.equals(s.getJSONObject("item").optString(field))&&s.optBoolean("playing"))return s;Thread.sleep(100);}throw new Exception("Playback wait failed "+value+" "+status());}
